/**
 * layers.ts — neural network layers with hand-derived forward and backward
 * passes. Each layer is its own small derivation; nothing is autogenerated.
 *
 * Convention: activations are Tensors. Conv/pool layers work on [C, H, W];
 * dense layers work on a flat vector (shape [N]).
 */

import {
  Tensor, Shape, numel, matmul, matmulNT, matmulTN, im2col, col2im, Im2ColInfo,
} from './tensor';

export interface Param {
  value: Tensor;
  grad: Tensor;
}

export interface Layer {
  readonly name: string;
  forward(x: Tensor): Tensor;
  backward(dy: Tensor): Tensor;
  params(): Param[];
}

/* ------------------------------------------------------------------ */
/* Dense (fully-connected)                                             */
/* ------------------------------------------------------------------ */

export class Dense implements Layer {
  readonly name = 'Dense';
  inFeatures: number;
  outFeatures: number;
  W: Param; // [out, in]
  b: Param; // [out]

  constructor(inFeatures: number, outFeatures: number) {
    this.inFeatures = inFeatures;
    this.outFeatures = outFeatures;
    // He initialisation for the square-root fan-in scaling
    const std = Math.sqrt(2 / inFeatures);
    this.W = {
      value: Tensor.randn([outFeatures, inFeatures], std),
      grad: Tensor.zeros([outFeatures, inFeatures]),
    };
    this.b = {
      value: Tensor.zeros([outFeatures]),
      grad: Tensor.zeros([outFeatures]),
    };
  }

  private xCache!: Float64Array;

  forward(x: Tensor): Tensor {
    this.xCache = x.data;
    const y = matmulNT(this.W.value.data, this.outFeatures, this.inFeatures, x.data, 1);
    for (let o = 0; o < this.outFeatures; o++) y[o] += this.b.value.data[o];
    return new Tensor(y, [this.outFeatures]);
  }

  backward(dy: Tensor): Tensor {
    // dW = dy[out,1] * x[1,in]  -> [out,in]
    const dW = matmul(dy.data, this.outFeatures, 1, this.xCache, this.inFeatures);
    for (let i = 0; i < dW.length; i++) this.W.grad.data[i] += dW[i];

    for (let o = 0; o < this.outFeatures; o++) this.b.grad.data[o] += dy.data[o];

    // dx = W^T * dy  -> [in]
    const dx = new Float64Array(this.inFeatures);
    for (let o = 0; o < this.outFeatures; o++) {
      const g = dy.data[o];
      if (g === 0) continue;
      const wRow = o * this.inFeatures;
      for (let i = 0; i < this.inFeatures; i++) dx[i] += this.W.value.data[wRow + i] * g;
    }
    return new Tensor(dx, [this.inFeatures]);
  }

  params(): Param[] {
    return [this.W, this.b];
  }
}

/* ------------------------------------------------------------------ */
/* 2D Convolution                                                      */
/* ------------------------------------------------------------------ */

export class Conv2D implements Layer {
  readonly name = 'Conv2D';
  inChannels: number;
  outChannels: number;
  kH: number;
  kW: number;
  stride: number;
  pad: number;
  W: Param; // [outC, inC*kH*kW]
  b: Param; // [outC]

  constructor(
    inChannels: number, outChannels: number,
    kH: number, kW: number, stride = 1, pad = 0,
  ) {
    this.inChannels = inChannels;
    this.outChannels = outChannels;
    this.kH = kH;
    this.kW = kW;
    this.stride = stride;
    this.pad = pad;
    const fanIn = inChannels * kH * kW;
    const std = Math.sqrt(2 / fanIn);
    this.W = {
      value: Tensor.randn([outChannels, fanIn], std),
      grad: Tensor.zeros([outChannels, fanIn]),
    };
    this.b = {
      value: Tensor.zeros([outChannels]),
      grad: Tensor.zeros([outChannels]),
    };
  }

  private colCache!: Float64Array;
  private infoCache!: Im2ColInfo;

  forward(x: Tensor): Tensor {
    const [C, H, W] = x.shape;
    const res = im2col(x.data, C, H, W, this.kH, this.kW, this.stride, this.pad);
    const { col, cols, rows, outH, outW } = res;
    this.colCache = col;
    this.infoCache = res;

    // out[outC, rows] = W[outC, cols] @ col[cols, rows]
    const out = matmul(this.W.value.data, this.outChannels, cols, col, rows);
    const bd = this.b.value.data;
    for (let o = 0; o < this.outChannels; o++) {
      const b = bd[o];
      const base = o * rows;
      for (let j = 0; j < rows; j++) out[base + j] += b;
    }
    return new Tensor(out, [this.outChannels, outH, outW]);
  }

  backward(dy: Tensor): Tensor {
    const { cols, rows } = this.infoCache;
    const dyM = dy.data; // [outC, rows]

    // dW = dY[outC, rows] * col^T[rows, cols]  => [outC, cols]
    const dW = matmul(dyM, this.outChannels, rows, this.colCache, cols);
    for (let i = 0; i < dW.length; i++) this.W.grad.data[i] += dW[i];

    // db = row-sums of dY
    for (let o = 0; o < this.outChannels; o++) {
      let s = 0;
      const base = o * rows;
      for (let j = 0; j < rows; j++) s += dyM[base + j];
      this.b.grad.data[o] += s;
    }

    // dcol = W^T[cols, outC] * dY[outC, rows] => [cols, rows]
    const dcol = matmulTN(this.W.value.data, cols, this.outChannels, dyM, rows);
    const dimg = col2im(dcol, this.infoCache);
    return new Tensor(dimg, [this.infoCache.channels, this.infoCache.inH, this.infoCache.inW]);
  }

  params(): Param[] {
    return [this.W, this.b];
  }
}

/* ------------------------------------------------------------------ */
/* Activation functions                                                */

export class ReLU implements Layer {
  readonly name = 'ReLU';
  private mask!: Uint8Array;

  forward(x: Tensor): Tensor {
    const out = new Float64Array(x.data.length);
    this.mask = new Uint8Array(x.data.length);
    for (let i = 0; i < x.data.length; i++) {
      if (x.data[i] > 0) {
        out[i] = x.data[i];
        this.mask[i] = 1;
      }
    }
    return new Tensor(out, x.shape.slice());
  }

  backward(dy: Tensor): Tensor {
    const out = new Float64Array(dy.data.length);
    for (let i = 0; i < dy.data.length; i++) out[i] = this.mask[i] ? dy.data[i] : 0;
    return new Tensor(out, dy.shape.slice());
  }

  params(): Param[] {
    return [];
  }
}

export class LeakyReLU implements Layer {
  readonly name = 'LeakyReLU';
  slope = 0.01;
  private mask!: Float64Array;

  forward(x: Tensor): Tensor {
    const out = new Float64Array(x.data.length);
    this.mask = new Float64Array(x.data.length);
    for (let i = 0; i < x.data.length; i++) {
      if (x.data[i] > 0) {
        out[i] = x.data[i];
        this.mask[i] = 1;
      } else {
        out[i] = x.data[i] * this.slope;
        this.mask[i] = this.slope;
      }
    }
    return new Tensor(out, x.shape.slice());
  }

  backward(dy: Tensor): Tensor {
    const out = new Float64Array(dy.data.length);
    for (let i = 0; i < dy.data.length; i++) out[i] = dy.data[i] * this.mask[i];
    return new Tensor(out, dy.shape.slice());
  }

  params(): Param[] {
    return [];
  }
}

export class Sigmoid implements Layer {
  readonly name = 'Sigmoid';
  private outCache!: Float64Array;

  forward(x: Tensor): Tensor {
    const out = new Float64Array(x.data.length);
    for (let i = 0; i < x.data.length; i++) out[i] = 1 / (1 + Math.exp(-x.data[i]));
    this.outCache = out;
    return new Tensor(out, x.shape.slice());
  }

  backward(dy: Tensor): Tensor {
    const out = new Float64Array(dy.data.length);
    for (let i = 0; i < dy.data.length; i++) {
      const s = this.outCache[i];
      out[i] = dy.data[i] * s * (1 - s);
    }
    return new Tensor(out, dy.shape.slice());
  }

  params(): Param[] {
    return [];
  }
}

export class Tanh implements Layer {
  readonly name = 'Tanh';
  private outCache!: Float64Array;

  forward(x: Tensor): Tensor {
    const out = new Float64Array(x.data.length);
    for (let i = 0; i < x.data.length; i++) out[i] = Math.tanh(x.data[i]);
    this.outCache = out;
    return new Tensor(out, x.shape.slice());
  }

  backward(dy: Tensor): Tensor {
    const out = new Float64Array(dy.data.length);
    for (let i = 0; i < dy.data.length; i++) {
      const t = this.outCache[i];
      out[i] = dy.data[i] * (1 - t * t);
    }
    return new Tensor(out, dy.shape.slice());
  }

  params(): Param[] {
    return [];
  }
}



/* ------------------------------------------------------------------ */
/* Max pooling                                                         */
/* ------------------------------------------------------------------ */

export class MaxPool2D implements Layer {
  readonly name = 'MaxPool2D';
  size: number;
  stride: number;
  private argmax!: Int32Array;
  private inShape!: Shape;

  constructor(size = 2, stride = size) {
    this.size = size;
    this.stride = stride;
  }

  forward(x: Tensor): Tensor {
    const [C, H, W] = x.shape;
    this.inShape = x.shape.slice();
    const outH = Math.floor((H - this.size) / this.stride) + 1;
    const outW = Math.floor((W - this.size) / this.stride) + 1;
    const out = new Float64Array(C * outH * outW);
    this.argmax = new Int32Array(C * outH * outW);

    for (let c = 0; c < C; c++) {
      for (let oy = 0; oy < outH; oy++) {
        for (let ox = 0; ox < outW; ox++) {
          let best = -Infinity;
          let bestIdx = -1;
          for (let ky = 0; ky < this.size; ky++) {
            for (let kx = 0; kx < this.size; kx++) {
              const iy = oy * this.stride + ky;
              const ix = ox * this.stride + kx;
              const idx = (c * H + iy) * W + ix;
              if (x.data[idx] > best) {
                best = x.data[idx];
                bestIdx = idx;
              }
            }
          }
          const oi = (c * outH + oy) * outW + ox;
          out[oi] = best;
          this.argmax[oi] = bestIdx;
        }
      }
    }
    return new Tensor(out, [C, outH, outW]);
  }

  backward(dy: Tensor): Tensor {
    const dx = new Float64Array(numel(this.inShape));
    for (let i = 0; i < dy.data.length; i++) dx[this.argmax[i]] += dy.data[i];
    return new Tensor(dx, this.inShape.slice());
  }

  params(): Param[] {
    return [];
  }
}

/* ------------------------------------------------------------------ */
/* Flatten / reshape                                                   */
/* ------------------------------------------------------------------ */

export class Flatten implements Layer {
  readonly name = 'Flatten';
  private inShape!: Shape;

  forward(x: Tensor): Tensor {
    this.inShape = x.shape.slice();
    return x.reshape([x.data.length]);
  }

  backward(dy: Tensor): Tensor {
    return new Tensor(dy.data.slice(), this.inShape.slice());
  }

  params(): Param[] {
    return [];
  }
}

/** Nearest-neighbour upsampling — used by the depth decoder. */
export class Upsample2D implements Layer {
  readonly name = 'Upsample2D';
  factor: number;
  private inShape!: Shape;

  constructor(factor = 2) {
    this.factor = factor;
  }

  forward(x: Tensor): Tensor {
    const [C, H, W] = x.shape;
    this.inShape = x.shape.slice();
    const f = this.factor;
    const outH = H * f;
    const outW = W * f;
    const out = new Float64Array(C * outH * outW);
    for (let c = 0; c < C; c++) {
      for (let y = 0; y < outH; y++) {
        const sy = Math.floor(y / f);
        for (let xx = 0; xx < outW; xx++) {
          const sx = Math.floor(xx / f);
          out[(c * outH + y) * outW + xx] = x.data[(c * H + sy) * W + sx];
        }
      }
    }
    return new Tensor(out, [C, outH, outW]);
  }

  backward(dy: Tensor): Tensor {
    const [C, H, W] = this.inShape;
    const f = this.factor;
    const outH = H * f;
    const outW = W * f;
    const dx = new Float64Array(C * H * W);
    const inv = 1 / (f * f);
    for (let c = 0; c < C; c++) {
      for (let y = 0; y < outH; y++) {
        const sy = Math.floor(y / f);
        for (let xx = 0; xx < outW; xx++) {
          const sx = Math.floor(xx / f);
          dx[(c * H + sy) * W + sx] += dy.data[(c * outH + y) * outW + xx] * inv;
        }
      }
    }
    return new Tensor(dx, this.inShape.slice());
  }

  params(): Param[] {
    return [];
  }
}

